module MemArbiter(
  input        clock,
               reset,
               io_req_0,
               io_req_1,
               io_req_2,
               io_req_3,
               io_free,
  output [1:0] io_pick,
  output       io_pickV
);

  reg  [1:0] turn;
  reg  [1:0] budget;
  reg        casez_tmp;
  always @(*) begin
    casez (turn)
      2'b00:
        casez_tmp = io_req_0;
      2'b01:
        casez_tmp = io_req_1;
      2'b10:
        casez_tmp = io_req_2;
      default:
        casez_tmp = io_req_3;
    endcase
  end // always @(*)
  wire       turnReady = casez_tmp & (|budget);
  wire [2:0] _GEN = {1'h0, turn};
  wire [2:0] afterIdx_t = _GEN + 3'h1;
  wire [1:0] afterIdx_0 = afterIdx_t[2] ? turn + 2'h1 : afterIdx_t[1:0];
  wire [2:0] afterIdx_t_1 = _GEN + 3'h2;
  wire [1:0] afterIdx_1 = afterIdx_t_1[2] ? turn - 2'h2 : afterIdx_t_1[1:0];
  wire [2:0] afterIdx_t_2 = _GEN + 3'h3;
  wire [1:0] afterIdx_2 = afterIdx_t_2[2] ? turn - 2'h1 : afterIdx_t_2[1:0];
  reg        casez_tmp_0;
  always @(*) begin
    casez (afterIdx_0)
      2'b00:
        casez_tmp_0 = io_req_0;
      2'b01:
        casez_tmp_0 = io_req_1;
      2'b10:
        casez_tmp_0 = io_req_2;
      default:
        casez_tmp_0 = io_req_3;
    endcase
  end // always @(*)
  reg        casez_tmp_1;
  always @(*) begin
    casez (afterIdx_1)
      2'b00:
        casez_tmp_1 = io_req_0;
      2'b01:
        casez_tmp_1 = io_req_1;
      2'b10:
        casez_tmp_1 = io_req_2;
      default:
        casez_tmp_1 = io_req_3;
    endcase
  end // always @(*)
  reg        casez_tmp_2;
  always @(*) begin
    casez (afterIdx_2)
      2'b00:
        casez_tmp_2 = io_req_0;
      2'b01:
        casez_tmp_2 = io_req_1;
      2'b10:
        casez_tmp_2 = io_req_2;
      default:
        casez_tmp_2 = io_req_3;
    endcase
  end // always @(*)
  reg  [1:0] casez_tmp_3;
  wire [3:0] afterIdx_t_3 = {2'h0, turn} + 4'h4;
  wire [1:0] _nextIdx_T_1 = casez_tmp_1 ? 2'h1 : {1'h1, ~casez_tmp_2};
  wire [1:0] _nextIdx_T_2 = casez_tmp_0 ? 2'h0 : _nextIdx_T_1;
  always @(*) begin
    casez (_nextIdx_T_2)
      2'b00:
        casez_tmp_3 = afterIdx_0;
      2'b01:
        casez_tmp_3 = afterIdx_1;
      2'b10:
        casez_tmp_3 = afterIdx_2;
      default:
        casez_tmp_3 = (|(afterIdx_t_3[3:2])) ? turn : afterIdx_t_3[1:0];
    endcase
  end // always @(*)
  wire [1:0] wrrIdx = turnReady ? turn : casez_tmp_3;
  reg  [5:0] age_0;
  reg  [5:0] age_1;
  reg  [5:0] age_2;
  reg  [5:0] age_3;
  wire       starveV_0 = io_req_0 & age_0[5];
  wire       starveV_1 = io_req_1 & age_1[5];
  wire       starveV_2 = io_req_2 & age_2[5];
  wire       starveV_3 = io_req_3 & age_3[5];
  wire [3:0] _starveAny_T = {starveV_3, starveV_2, starveV_1, starveV_0};
  wire [1:0] _starveIdx_T_4 = {1'h0, starveV_1 & (age_1 > age_0 | ~starveV_0)};
  reg  [5:0] casez_tmp_4;
  always @(*) begin
    casez (_starveIdx_T_4)
      2'b00:
        casez_tmp_4 = age_0;
      2'b01:
        casez_tmp_4 = age_1;
      2'b10:
        casez_tmp_4 = age_2;
      default:
        casez_tmp_4 = age_3;
    endcase
  end // always @(*)
  reg        casez_tmp_5;
  always @(*) begin
    casez (_starveIdx_T_4)
      2'b00:
        casez_tmp_5 = starveV_0;
      2'b01:
        casez_tmp_5 = starveV_1;
      2'b10:
        casez_tmp_5 = starveV_2;
      default:
        casez_tmp_5 = starveV_3;
    endcase
  end // always @(*)
  wire [1:0] _starveIdx_T_9 =
    starveV_2 & (age_2 > casez_tmp_4 | ~casez_tmp_5) ? 2'h2 : _starveIdx_T_4;
  reg  [5:0] casez_tmp_6;
  always @(*) begin
    casez (_starveIdx_T_9)
      2'b00:
        casez_tmp_6 = age_0;
      2'b01:
        casez_tmp_6 = age_1;
      2'b10:
        casez_tmp_6 = age_2;
      default:
        casez_tmp_6 = age_3;
    endcase
  end // always @(*)
  reg        casez_tmp_7;
  always @(*) begin
    casez (_starveIdx_T_9)
      2'b00:
        casez_tmp_7 = starveV_0;
      2'b01:
        casez_tmp_7 = starveV_1;
      2'b10:
        casez_tmp_7 = starveV_2;
      default:
        casez_tmp_7 = starveV_3;
    endcase
  end // always @(*)
  wire [1:0] starveIdx =
    starveV_3 & (age_3 > casez_tmp_6 | ~casez_tmp_7) ? 2'h3 : _starveIdx_T_9;
  wire [1:0] pickIdx = (|_starveAny_T) ? starveIdx : wrrIdx;
  wire       grant = io_free & (|{io_req_3, io_req_2, io_req_1, io_req_0});
  reg  [1:0] casez_tmp_8;
  always @(*) begin
    casez (casez_tmp_3)
      2'b00:
        casez_tmp_8 = 2'h2;
      2'b01:
        casez_tmp_8 = 2'h1;
      2'b10:
        casez_tmp_8 = 2'h1;
      default:
        casez_tmp_8 = 2'h1;
    endcase
  end // always @(*)
  wire       served = grant & pickIdx == 2'h0;
  wire       served_1 = grant & pickIdx == 2'h1;
  wire       served_2 = grant & pickIdx == 2'h2;
  wire       served_3 = grant & (&pickIdx);
  always @(posedge clock) begin
    if (reset) begin
      turn <= 2'h0;
      budget <= 2'h0;
      age_0 <= 6'h0;
      age_1 <= 6'h0;
      age_2 <= 6'h0;
      age_3 <= 6'h0;
    end
    else begin
      if (grant) begin
        if (|_starveAny_T) begin
          turn <= starveIdx;
          budget <= 2'h0;
        end
        else if (turnReady)
          budget <= budget - 2'h1;
        else begin
          turn <= casez_tmp_3;
          budget <= casez_tmp_8 - 2'h1;
        end
      end
      if (~io_req_0 | served)
        age_0 <= 6'h0;
      else if (~(io_free & io_req_0 & ~served) | (&age_0)) begin
      end
      else
        age_0 <= age_0 + 6'h1;
      if (~io_req_1 | served_1)
        age_1 <= 6'h0;
      else if (~(io_free & io_req_1 & ~served_1) | (&age_1)) begin
      end
      else
        age_1 <= age_1 + 6'h1;
      if (~io_req_2 | served_2)
        age_2 <= 6'h0;
      else if (~(io_free & io_req_2 & ~served_2) | (&age_2)) begin
      end
      else
        age_2 <= age_2 + 6'h1;
      if (~io_req_3 | served_3)
        age_3 <= 6'h0;
      else if (~(io_free & io_req_3 & ~served_3) | (&age_3)) begin
      end
      else
        age_3 <= age_3 + 6'h1;
    end
  end // always @(posedge)
  assign io_pick = pickIdx;
  assign io_pickV = grant;
endmodule

